import React, { useState, useCallback, useEffect } from 'react';
import {
  View, Text, StyleSheet, TouchableOpacity, Alert, Vibration, AppState,
} from 'react-native';
import { useNavigation } from '@react-navigation/native';
import { useAuthStore } from '../stores/authStore';
import { getDeviceId } from '../utils/device';
import api from '../services/api';

// 扫码组件使用 react-native-vision-camera
// 以下为完整实现骨架，CodeScanner 需在原生环境运行

interface ScanResult {
  success: boolean;
  message: string;
  scan_count?: number;
  max_scan_count?: number;
  box_type?: string;
  error_code?: string;
}

export default function ScanScreen() {
  const navigation = useNavigation<any>();
  const { user, logout } = useAuthStore();
  const [lastResult, setLastResult] = useState<ScanResult | null>(null);
  const [scanning, setScanning] = useState(false);
  const [torchOn, setTorchOn] = useState(false);

  // 进入扫码页强制开启手电筒
  useEffect(() => {
    setTorchOn(true);
    return () => setTorchOn(false); // 离开页面关闭
  }, []);

  const handleBarCodeScanned = useCallback(async (code: string) => {
    if (scanning) return; // 防止连续扫描请求堆积
    setScanning(true);

    try {
      const deviceId = getDeviceId();
      const res = await api.post('/scan', { code, device_id: deviceId });
      const result: ScanResult = res.data;
      setLastResult(result);

      if (result.success) {
        Vibration.vibrate(100);
      } else {
        // 失败时震动+红色提示
        Vibration.vibrate([200, 100, 200]);
        Alert.alert('扫描提示', result.message);
      }
    } catch (e: any) {
      const msg = e.response?.data?.message || '网络不可用';
      setLastResult({ success: false, message: msg, error_code: 'NETWORK_ERROR' });
      Alert.alert('错误', msg);
    } finally {
      // 短暂延迟后允许下一次扫描（连续扫描模式）
      setTimeout(() => setScanning(false), 500);
    }
  }, [scanning]);

  const getResultColor = () => {
    if (!lastResult) return '#d9d9d9';
    return lastResult.success ? '#52c41a' : '#ff4d4f';
  };

  return (
    <View style={styles.container}>
      {/* 顶部栏 */}
      <View style={styles.header}>
        <Text style={styles.headerTitle}>{user?.code}</Text>
        <TouchableOpacity onPress={() => navigation.navigate('Profile')}>
          <Text style={styles.profileBtn}>个人</Text>
        </TouchableOpacity>
      </View>

      {/* 扫码区域 */}
      <View style={styles.scannerArea}>
        <View style={styles.scannerFrame}>
          <Text style={styles.scannerHint}>将二维码对准框内</Text>
          {/* CodeScanner 组件在此挂载 */}
          {/* <CodeScanner
            style={StyleSheet.absoluteFill}
            onCodeScanned={handleBarCodeScanned}
            torch={torchOn ? 'on' : 'off'}
          /> */}
          <View style={[styles.scanLine, { backgroundColor: getResultColor() }]} />
        </View>
      </View>

      {/* 结果面板 */}
      <View style={[styles.resultPanel, { borderColor: getResultColor() }]}>
        {lastResult ? (
          <>
            <Text style={[styles.resultText, { color: getResultColor() }]}>
              {lastResult.success ? '✔ 扫描成功' : '✖ ' + lastResult.message}
            </Text>
            {lastResult.scan_count !== undefined && (
              <Text style={styles.scanCount}>
                已扫描 {lastResult.scan_count} / {lastResult.max_scan_count} 次
                {lastResult.box_type && ` (${lastResult.box_type})`}
              </Text>
            )}
          </>
        ) : (
          <Text style={styles.placeholderText}>等待扫描...</Text>
        )}
      </View>

      {/* 手电筒指示 */}
      <View style={styles.torchIndicator}>
        <Text style={styles.torchText}>手电筒: {torchOn ? '开启' : '关闭'}</Text>
      </View>
    </View>
  );
}

const styles = StyleSheet.create({
  container: { flex: 1, backgroundColor: '#000' },
  header: {
    flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center',
    paddingHorizontal: 20, paddingTop: 50, paddingBottom: 16, backgroundColor: '#001529',
  },
  headerTitle: { color: '#fff', fontSize: 18, fontWeight: 'bold' },
  profileBtn: { color: '#1677ff', fontSize: 16 },
  scannerArea: { flex: 2, justifyContent: 'center', alignItems: 'center' },
  scannerFrame: {
    width: 260, height: 260, borderWidth: 2, borderColor: '#1677ff',
    borderRadius: 16, justifyContent: 'center', alignItems: 'center',
  },
  scannerHint: { color: '#fff', position: 'absolute', top: -30, fontSize: 14 },
  scanLine: { width: 240, height: 2, position: 'absolute', top: 130 },
  resultPanel: {
    flex: 1, borderTopWidth: 3, borderTopColor: '#333',
    padding: 24, backgroundColor: '#1a1a1a', justifyContent: 'center', alignItems: 'center',
  },
  resultText: { fontSize: 20, fontWeight: 'bold', marginBottom: 12 },
  scanCount: { fontSize: 16, color: '#aaa' },
  placeholderText: { fontSize: 16, color: '#666' },
  torchIndicator: { padding: 16, alignItems: 'center' },
  torchText: { color: '#aaa', fontSize: 13 },
});
